"use client";

import React, { useEffect, useState } from "react";
import { api } from "@/lib/api";
import { useCurrentUser } from "@/hooks/use-current-user";
import { Tenant, User } from "@/types";

export default function SettingsPage() {
  const { currentUser, loading } = useCurrentUser();
  const [tenant, setTenant] = useState<Tenant | null>(null);
  const [fullName, setFullName] = useState("");
  const [email, setEmail] = useState("");
  const [businessName, setBusinessName] = useState("");
  const [businessPhone, setBusinessPhone] = useState("");
  const [twilioNumber, setTwilioNumber] = useState("");
  const [savingProfile, setSavingProfile] = useState(false);
  const [savingBusiness, setSavingBusiness] = useState(false);

  useEffect(() => {
    if (!currentUser) return;
    setFullName(currentUser.name);
    setEmail(currentUser.email);

    (async () => {
      const t = await api.getTenant(currentUser.tenantId);
      if (t) {
        setTenant(t);
        setBusinessName(t.businessName || "");
        setBusinessPhone(t.businessPhone || "");
        setTwilioNumber(t.twilioNumber || "Not provisioned yet");
      }
    })();
  }, [currentUser]);

  async function handleSaveProfile() {
    if (!currentUser) return;
    setSavingProfile(true);
    const updated = await api.updateUser(currentUser.id, {
      name: fullName,
      email,
    });
    setFullName(updated.name);
    setEmail(updated.email);
    setSavingProfile(false);
  }

  async function handleSaveBusiness() {
    if (!currentUser || !tenant) return;
    setSavingBusiness(true);
    const updated = await api.updateTenant(tenant.id, {
      businessName,
      businessPhone,
    });
    setTenant(updated);
    setSavingBusiness(false);
  }

  if (loading) {
    return (
      <div className="flex items-center justify-center h-[60vh]">
        <div className="h-8 w-8 rounded-full border-2 border-brand-primary border-t-transparent animate-spin" />
      </div>
    );
  }

  if (!currentUser) {
    return <p className="text-sm text-dark-text-secondary">Not logged in.</p>;
  }

  return (
    <div className="max-w-4xl mx-auto space-y-8">
      {/* Profile */}
      <div className="bg-dark-card rounded-xl border border-slate-800/40">
        <div className="p-6 border-b border-slate-800/40">
          <h2 className="text-xl font-semibold text-white">Profile</h2>
          <p className="text-sm text-dark-text-secondary mt-1">
            Manage your account details.
          </p>
        </div>
        <div className="p-6 space-y-4">
          <div>
            <label
              htmlFor="fullName"
              className="block text-sm text-dark-text-secondary mb-1"
            >
              Full name
            </label>
            <input
              id="fullName"
              name="fullName"
              value={fullName}
              onChange={(e) => setFullName(e.target.value)}
              className="w-full bg-slate-900/50 border border-slate-700 rounded-md px-3 py-2 text-white outline-none focus:ring-2 focus:ring-brand-primary"
              placeholder="Omer Geva"
            />
          </div>
          <div>
            <label
              htmlFor="email"
              className="block text-sm text-dark-text-secondary mb-1"
            >
              Email address
            </label>
            <input
              id="email"
              name="email"
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              className="w-full bg-slate-900/50 border border-slate-700 rounded-md px-3 py-2 text-white outline-none focus:ring-2 focus:ring-brand-primary"
              placeholder="you@sylor.ai"
              type="email"
            />
          </div>
        </div>
        <div className="p-6 border-t border-slate-800/40 text-right">
          <button
            onClick={handleSaveProfile}
            disabled={savingProfile}
            className="bg-brand-primary hover:bg-brand-secondary px-4 py-2 rounded-md text-sm font-semibold text-white disabled:opacity-60"
          >
            {savingProfile ? "Saving..." : "Save profile"}
          </button>
        </div>
      </div>

      {/* Business */}
      <div className="bg-dark-card rounded-xl border border-slate-800/40">
        <div className="p-6 border-b border-slate-800/40">
          <h2 className="text-xl font-semibold text-white">
            Business settings
          </h2>
          <p className="text-sm text-dark-text-secondary mt-1">
            This is what leads will see in SMS.
          </p>
        </div>
        <div className="p-6 space-y-4">
          <div>
            <label
              htmlFor="businessName"
              className="block text-sm text-dark-text-secondary mb-1"
            >
              Business name
            </label>
            <input
              id="businessName"
              name="businessName"
              value={businessName}
              onChange={(e) => setBusinessName(e.target.value)}
              className="w-full bg-slate-900/50 border border-slate-700 rounded-md px-3 py-2 text-white"
              placeholder="UrbanLux Construction"
            />
          </div>
          <div>
            <label
              htmlFor="businessPhone"
              className="block text-sm text-dark-text-secondary mb-1"
            >
              Business phone
            </label>
            <input
              id="businessPhone"
              name="businessPhone"
              value={businessPhone}
              onChange={(e) => setBusinessPhone(e.target.value)}
              className="w-full bg-slate-900/50 border border-slate-700 rounded-md px-3 py-2 text-white"
              placeholder="+1 (818) 555-1234"
            />
          </div>
          <div>
            <label
              htmlFor="twilioNumber"
              className="block text-sm text-dark-text-secondary mb-1"
            >
              Sylor AI number (read-only)
            </label>
            <input
              id="twilioNumber"
              name="twilioNumber"
              value={twilioNumber}
              readOnly
              className="w-full bg-slate-900/30 border border-slate-800 rounded-md px-3 py-2 text-dark-text-secondary cursor-not-allowed"
            />
          </div>
        </div>
        <div className="p-6 border-t border-slate-800/40 text-right">
          <button
            onClick={handleSaveBusiness}
            disabled={savingBusiness}
            className="bg-brand-primary hover:bg-brand-secondary px-4 py-2 rounded-md text-sm font-semibold text-white disabled:opacity-60"
          >
            {savingBusiness ? "Saving..." : "Save business"}
          </button>
        </div>
      </div>
    </div>
  );
}
